def finalize(obj, memo):
    if id(obj) in memo:
        return memo[id(obj)]
    if isinstance(obj, list):
        if id(obj) in placeholder_ids:  # placeholder for tuple
            new_tuple = tuple(finalize(e, memo) for e in obj)
            memo[id(obj)] = new_tuple
            return new_tuple
        else:
            new_list = []
            memo[id(obj)] = new_list
            for e in obj:
                new_list.append(finalize(e, memo))
            return new_list
    elif isinstance(obj, dict):
        new_dict = {}
        memo[id(obj)] = new_dict
        for k, v in obj.items():
            new_k = finalize(k, memo)
            new_v = finalize(v, memo)
            new_dict[new_k] = new_v
        return new_dict
    else:
        return obj

