def clone_with_placeholders(o, memo, placeholder_ids):
    oid = id(o)
    if oid in memo:
        return memo[oid]
    if isinstance(o, dict):
        new = {}
        memo[oid] = new
        for k, v in o.items():
            new_k = clone_with_placeholders(k, memo, placeholder_ids)
            new_v = clone_with_placeholders(v, memo, placeholder_ids)
            new[new_k] = new_v
        return new
    elif isinstance(o, list):
        new = []
        memo[oid] = new
        for e in o:
            new.append(clone_with_placeholders(e, memo, placeholder_ids))
        return new
    elif isinstance(o, tuple):
        new_placeholder = []
        memo[oid] = new_placeholder
        placeholder_ids.add(id(new_placeholder))
        for e in o:
            new_placeholder.append(clone_with_placeholders(e, memo, placeholder_ids))
        return new_placeholder
    else:
        return o

